from sympy import symbols, sympify, tan, sec, atan, log, integrate, simplify

x, r, theta = symbols("x r theta")

def theta_integral(g):
    # the integrals of sec and sec^3 from Trigonometric Integrals, and sympy for the rest
    c = simplify(g / sec(theta))
    if not c.has(theta):
        return c * log(sec(theta) + tan(theta))
    c = simplify(g / sec(theta)**3)
    if not c.has(theta):
        return c * (sec(theta) * tan(theta) + log(sec(theta) + tan(theta))) / 2
    return integrate(g, theta)

n = int(input())
for i in range(1, n + 1):
    a = sympify(input())
    f = sympify(input())
    print(f"problem {i}: a = {a}, integrand {f}")
    g = simplify(f.subs({x: a*tan(theta), r: a*sec(theta)}) * a*sec(theta)**2)
    print(f"  in theta: {g}")
    print(f"  answer: {simplify(theta_integral(g).subs(theta, atan(x / a)))} + C")

